179	func cmdHandoff(dataFile string, argv []string, stdout, stderr io.Writer) int {
180		fs := newFlagSet("handoff", stderr)
181		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
182		request := fs.String("request", "", "交接请求号（用于去重）")
183		from := fs.String("from", "", "源站点")
184		to := fs.String("to", "", "目的站点")
185		var parcels stringList
186		fs.Var(&parcels, "parcel", "包裹编号，可重复指定；集合不可为空或含重复编号")
187		if ok, code := parseFlags(fs, argv, stdout, stderr, printHandoffHelp); !ok {
188			return code
189		}
190	
191		cleanReq, err := cleanID("请求号", *request)
192		if err != nil {
193			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
194			return exitBusiness
195		}
196		cleanFrom, err := cleanID("源站点", *from)
197		if err != nil {
198			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
199			return exitBusiness
200		}
201		cleanTo, err := cleanID("目的站点", *to)
202		if err != nil {
203			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
204			return exitBusiness
205		}
206		if len(parcels) == 0 {
207			fmt.Fprintf(stderr, "%s handoff: 包裹集合不可为空，至少需要一个 --parcel\n", appName)
208			return exitBusiness
209		}
210		cleanParcels := make([]string, 0, len(parcels))
211		seen := make(map[string]bool, len(parcels))
212		for _, raw := range parcels {
213			id, err := cleanID("包裹编号", raw)
214			if err != nil {
215				fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
216				return exitBusiness
217			}
218			if seen[id] {
219				fmt.Fprintf(stderr, "%s handoff: 包裹集合中编号 %q 重复\n", appName, id)
220				return exitBusiness
221			}
222			seen[id] = true
223			cleanParcels = append(cleanParcels, id)
224		}
225		if cleanFrom == cleanTo {
226			fmt.Fprintf(stderr, "%s handoff: 源站点与目的站点不能相同（均为 %q）\n", appName, cleanFrom)
227			return exitBusiness
228		}
229	
230		store, release, err := OpenForUpdate(dataFile)
231		if err != nil {
232			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
233			return exitBusiness
234		}
235		defer release()
236		result, replayed, err := store.Handoff(cleanReq, cleanFrom, cleanTo, cleanParcels, now())
237		if err != nil {
238			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
239			return exitBusiness
240		}
241	
242		headline := "交接成功"
243		if replayed {
244			headline = "交接成功（请求号重复提交，返回首次保存的结果，未再追加轨迹）"
245		}
246		fmt.Fprintf(stdout, "%s\n请求号: %s\n源站点: %s\n目的站点: %s\n包裹（%d 件）:\n",
247			headline, result.Request, result.From, result.To, len(result.Parcels))
248		for _, id := range result.Parcels {
249			fmt.Fprintf(stdout, "  - %s\n", id)
250		}
251		fmt.Fprintf(stdout, "发生时间: %s\n", result.Time.Format(timeFmt))
252		return exitOK
253	}
