541	func cmdReceiptImport(dataFile string, argv []string, stdout, stderr io.Writer) int {
542		fs := newFlagSet("receipt-import", stderr)
543		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
544		file := fs.String("file", "", "回执导入文件路径（JSON 数组，只读，不会被修改）")
545		if ok, code := parseFlags(fs, argv, stdout, stderr, printReceiptImportHelp); !ok {
546			return code
547		}
548	
549		if strings.TrimSpace(*file) == "" {
550			fmt.Fprintf(stderr, "%s receipt-import: 选项 --file 需要一个非空的回执导入文件路径\n", appName)
551			return exitBusiness
552		}
553	
554		// 输入文件只读；读取、解析或清洗失败时整份不予导入。
555		records, err := loadReceiptImportFile(*file)
556		if err != nil {
557			fmt.Fprintf(stderr, "%s receipt-import: %v\n", appName, err)
558			return exitBusiness
559		}
560	
561		store, release, err := OpenForUpdate(dataFile)
562		if err != nil {
563			fmt.Fprintf(stderr, "%s receipt-import: %v\n", appName, err)
564			return exitBusiness
565		}
566		defer release()
567		items, err := store.ImportReceipts(records, now())
568		if err != nil {
569			fmt.Fprintf(stderr, "%s receipt-import: %v\n", appName, err)
570			return exitBusiness
571		}
572	
573		replayed := 0
574		for _, it := range items {
575			if it.Replayed {
576				replayed++
577			}
578		}
579		fmt.Fprintf(stdout, "回执导入成功（共 %d 条：新增 %d 条，重放 %d 条）\n", len(items), len(items)-replayed, replayed)
580		for i, it := range items {
581			mark := "新增"
582			if it.Replayed {
583				mark = "重放（返回首次保存的结果）"
584			}
585			if it.Revoked {
586				mark += "，该回执已撤销"
587			}
588			line := fmt.Sprintf("  %d. 请求号: %s    批次号: %s    包裹编号: %s    结果: %s",
589				i+1, it.Record.Request, it.Record.Batch, it.Record.Parcel, it.Record.Result)
590			if it.Record.Result == resultFailed {
591				line += fmt.Sprintf("    原因: %s", it.Record.Reason)
592			}
593			fmt.Fprintf(stdout, "%s    标记: %s    时间: %s\n", line, mark, it.Time.Format(timeFmt))
594		}
595		return exitOK
596	}
