645	func cmdBatch(dataFile string, argv []string, stdout, stderr io.Writer) int {
646		fs := newFlagSet("batch", stderr)
647		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
648		id := fs.String("id", "", "要查询的配送批次号")
649		if ok, code := parseFlags(fs, argv, stdout, stderr, printBatchHelp); !ok {
650			return code
651		}
652	
653		cleanIDVal, err := cleanID("批次号", *id)
654		if err != nil {
655			fmt.Fprintf(stderr, "%s batch: %v\n", appName, err)
656			return exitBusiness
657		}
658	
659		store, err := Open(dataFile)
660		if err != nil {
661			fmt.Fprintf(stderr, "%s batch: %v\n", appName, err)
662			return exitBusiness
663		}
664		b, err := store.BatchQuery(cleanIDVal)
665		if err != nil {
666			fmt.Fprintf(stderr, "%s batch: %v\n", appName, err)
667			return exitBusiness
668		}
669	
670		status := "配送中"
671		if b.Done() {
672			status = "已完成"
673		}
674		ab := store.BatchAbort(cleanIDVal)
675		if ab != nil {
676			status = "已中止"
677		}
678		tr := store.BatchTransferSource(cleanIDVal)
679		if tr != nil {
680			status = "已转交"
681		}
682		timeLabel := "出站时间"
683		if b.RelayedFrom != "" {
684			timeLabel = "接手时间"
685		}
686		fmt.Fprintf(stdout, "批次号: %s\n出发站: %s\n配送员: %s\n%s: %s\n批次状态: %s\n",
687			b.Batch, b.Station, b.Courier, timeLabel, b.Time.Format(timeFmt), status)
688		if b.RelayedFrom != "" {
689			src := store.TransferOf(b.RelayRequest)
690			fmt.Fprintf(stdout, "批次来源: 续接自批次 %s（原配送员: %s，续接请求号: %s）\n",
691				b.RelayedFrom, src.FromCourier, b.RelayRequest)
692		}
693		if ab != nil {
694			fmt.Fprintf(stdout, "中止请求号: %s\n中止原因: %s\n中止时间: %s\n",
695				ab.Request, ab.Reason, ab.Time.Format(timeFmt))
696		}
697		if tr != nil {
698			fmt.Fprintf(stdout, "转交去向: 批次 %s（新配送员: %s）\n续接请求号: %s\n续接原因: %s\n转交时间: %s\n",
699				tr.ToBatch, tr.ToCourier, tr.Request, tr.Reason, tr.Time.Format(timeFmt))
700		}
701		fmt.Fprintf(stdout, "逐件回执（%d/%d 已回执）:\n", b.Effective(), len(b.Parcels))
702		for _, pid := range b.Parcels {
703			e, ok := b.Receipts[pid]
704			if !ok || e.RevokedBy != "" {
705				switch {
706				case tr != nil:
707					fmt.Fprintf(stdout, "  - %s    已转交    去向批次: %s    续接请求号: %s    时间: %s\n",
708						pid, tr.ToBatch, tr.Request, tr.Time.Format(timeFmt))
709				case ab != nil:
710					fmt.Fprintf(stdout, "  - %s    已收回    中止请求号: %s    原因: %s    时间: %s\n",
711						pid, ab.Request, ab.Reason, ab.Time.Format(timeFmt))
712				case ok:
713					fmt.Fprintf(stdout, "  - %s    未回执（原回执 %s 已撤销，撤销请求号: %s）\n", pid, e.Request, e.RevokedBy)
714				default:
715					fmt.Fprintf(stdout, "  - %s    未回执\n", pid)
716				}
717				continue
718			}
719			if e.Result == resultFailed {
720				fmt.Fprintf(stdout, "  - %s    已回执    结果: %s    原因: %s    请求号: %s    时间: %s\n",
721					pid, e.Result, e.Reason, e.Request, e.Time.Format(timeFmt))
722			} else {
723				fmt.Fprintf(stdout, "  - %s    已回执    结果: %s    请求号: %s    时间: %s\n",
724					pid, e.Result, e.Request, e.Time.Format(timeFmt))
725			}
726		}
727		if rvs := store.BatchRevokes(cleanIDVal); len(rvs) > 0 {
728			fmt.Fprintf(stdout, "撤销记录（%d 条）:\n", len(rvs))
729			for _, rv := range rvs {
730				fmt.Fprintf(stdout, "  - 撤销请求号: %s    原回执请求号: %s    包裹: %s    批次: %s    原因: %s    时间: %s\n",
731					rv.Request, rv.Receipt, rv.Parcel, rv.Batch, rv.Reason, rv.Time.Format(timeFmt))
732			}
733		}
734		return exitOK
735	}
