		fmt.Fprintf(stderr, "%s freeze: %v\n", appName, err)
		return exitBusiness
	}
	defer release()
	res, replayed, err := store.Freeze(cleanIncident, cleanParcel, cleanStation, cleanReason, now())
	if err != nil {
		fmt.Fprintf(stderr, "%s freeze: %v\n", appName, err)
		return exitBusiness
	}

	headline := "冻结成功"
