1076	// Register 执行单件收件登记并将结果整体落盘。
1077	func (s *Store) Register(id, station string, now time.Time) (*Parcel, error) {
1078		if _, ok := s.data.Parcels[id]; ok {
1079			return nil, fmt.Errorf("包裹编号 %q 已登记，不能重复登记", id)
1080		}
1081		p := &Parcel{
1082			ID:         id,
1083			Station:    station,
1084			Status:     statusInStation,
1085			Registered: now,
1086			Trail: []Event{{
1087				Op:      "收件",
1088				Station: station,
1089				Time:    now,
1090			}},
1091		}
1092		s.data.Parcels[id] = p
1093		if err := s.save(); err != nil {
1094			delete(s.data.Parcels, id) // 落盘失败：回滚内存变更，保留原有有效数据
1095			return nil, err
1096		}
1097		return p, nil
1098	}
