1101	func (s *Store) Query(id string) (*Parcel, error) {
1102		p, ok := s.data.Parcels[id]
1103		if !ok {
1104			return nil, fmt.Errorf("%w: %q", ErrNotFound, id)
1105		}
1106		return p, nil
1107	}
