1109	// ActiveFreeze 返回一件包裹当前未解除异常单的冻结结果；包裹不存在或当前未冻结时返回 nil。
1110	func (s *Store) ActiveFreeze(id string) *FreezeResult {
1111		p, ok := s.data.Parcels[id]
1112		if !ok {
1113			return nil
1114		}
1115		if no := activeFreeze(p); no != "" {
1116			return s.data.Freezes[no]
1117		}
1118		return nil
1119	}
