1121	// Handoff 提交一次多件包裹的站点交接。
1122	//
1123	// 首次提交：所有包裹必须已登记且当前归属源站点，否则整次失败、不作任何改动；
1124	// 全部满足时一起改归目的站点并各追加一条交接记录，作为一个整体保存。
1125	// 相同请求号且业务内容（源、目的、包裹集合，与顺序无关）相同：直接返回首次结果，
1126	// 返回值 replayed 为 true；相同请求号但业务内容不同：报冲突，已有结果不变。
1127	func (s *Store) Handoff(request, from, to string, parcels []string, now time.Time) (result *HandoffResult, replayed bool, err error) {
1128		if saved, ok := s.data.Handoffs[request]; ok {
1129			if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
1130				return saved, true, nil
1131			}
1132			return nil, false, fmt.Errorf("请求号 %q 已用于一次不同的交接（源=%q 目的=%q），内容冲突", request, saved.From, saved.To)
1133		}
1134	
1135		// 首次提交：先做全部校验，任何一件不满足都整体失败。
1136		for _, id := range parcels {
1137			p, ok := s.data.Parcels[id]
1138			if !ok {
1139				return nil, false, fmt.Errorf("交接失败：包裹 %q 未登记，整次交接未执行", id)
1140			}
1141			if p.Station != from {
1142				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前归属 %q，不属于源站点 %q，整次交接未执行", id, p.Station, from)
1143			}
1144			if inc := activeFreeze(p); inc != "" {
1145				return nil, false, fmt.Errorf("交接失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批交接拒绝，整次交接未执行", id, inc)
1146			}
1147			if p.Status != statusInStation {
1148				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前状态为 %q，不是在站，整次交接未执行", id, p.Status)
1149			}
1150		}
1151	
1152		res := &HandoffResult{
1153			Request: request,
1154			From:    from,
1155			To:      to,
1156			Parcels: append([]string(nil), parcels...),
1157			Time:    now,
1158		}
1159		s.data.Handoffs[request] = res
1160	
1161		// 记录旧值，落盘失败时整体回滚。
1162		prev := make(map[string]struct {
1163			station string
1164			trail   []Event
1165		}, len(parcels))
1166		for _, id := range parcels {
1167			p := s.data.Parcels[id]
1168			prev[id] = struct {
1169				station string
1170				trail   []Event
1171			}{p.Station, append([]Event(nil), p.Trail...)}
1172			p.Station = to
1173			p.Status = statusInStation
1174			p.Trail = append(p.Trail, Event{
1175				Op:      "交接",
1176				Station: to,
1177				Request: request,
1178				Time:    now,
1179			})
1180		}
1181	
1182		if err := s.save(); err != nil {
1183			delete(s.data.Handoffs, request)
1184			for id, old := range prev {
1185				p := s.data.Parcels[id]
1186				p.Station = old.station
1187				p.Trail = old.trail
1188			}
1189			return nil, false, err
1190		}
1191		return res, false, nil
1192	}
1193	
1194	// Return 按原交接整批退回：实物送回该交接的源站点，批次与站点取自原交接结果。
1195	//
1196	// 首次退回：原交接必须存在且尚未成功退回；批次中每件包裹必须仍归属原交接目的站、
1197	// 状态为在站，且最后一条流转记录就是该原交接（请求重放不产生新流转，不影响判定）。
1198	// 任一条件不满足则整批拒绝，不作任何改动。全部满足时整批改归原交接源站（仍为在站），
1199	// 每件按批次顺序追加一条退回记录，原收件、交接轨迹保留不变。
1200	// 相同退回请求号且原交接、原因相同：直接返回首次结果，replayed 为 true，
1201	// 即使包裹之后又被交接也不重新检查；请求号相同但原交接或原因不同：报冲突。
1202	// 退回请求号与交接请求号分属独立去重范围，互不影响；失败的首次退回不占用请求号。
1203	func (s *Store) Return(request, handoffReq, reason string, now time.Time) (result *ReturnResult, replayed bool, err error) {
1204		if saved, ok := s.data.Returns[request]; ok {
1205			if saved.Handoff == handoffReq && saved.Reason == reason {
1206				return saved, true, nil
1207			}
1208			return nil, false, fmt.Errorf("退回请求号 %q 已用于一次不同的退回（原交接=%q 原因=%q），内容冲突",
1209				request, saved.Handoff, saved.Reason)
1210		}
1211	
1212		h, ok := s.data.Handoffs[handoffReq]
1213		if !ok {
1214			return nil, false, fmt.Errorf("退回失败：原交接请求号 %q 不存在", handoffReq)
1215		}
1216		if h.ReturnedBy != "" {
1217			return nil, false, fmt.Errorf("退回失败：原交接 %q 已成功退回（退回请求号 %q），不能再次退回", handoffReq, h.ReturnedBy)
1218		}
1219	
1220		// 先做全部校验，任何一件不满足都整批拒绝。
1221		for _, id := range h.Parcels {
1222			p, ok := s.data.Parcels[id]
1223			if !ok {
1224				return nil, false, fmt.Errorf("退回失败：包裹 %q 未登记，整批退回未执行", id)
1225			}
1226			if inc := activeFreeze(p); inc != "" {
1227				return nil, false, fmt.Errorf("退回失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批退回拒绝，整批退回未执行", id, inc)
1228			}
1229			if p.Station != h.To || p.Status != statusInStation {
1230				return nil, false, fmt.Errorf("退回失败：包裹 %q 当前归属 %q、状态 %q，不在原交接目的站 %q 在站，整批退回未执行",
1231					id, p.Station, p.Status, h.To)
1232			}
1233			last := lastFlowEvent(p.Trail)
1234			if last.Op != "交接" || last.Request != handoffReq {
1235				return nil, false, fmt.Errorf("退回失败：包裹 %q 在原交接 %q 之后又有新的流转，不能退回该交接，整批退回未执行",
1236					id, handoffReq)
1237			}
1238		}
1239	
1240		res := &ReturnResult{
1241			Request: request,
1242			Handoff: handoffReq,
1243			From:    h.To,
1244			To:      h.From,
1245			Reason:  reason,
1246			Parcels: append([]string(nil), h.Parcels...),
1247			Time:    now,
1248		}
1249		s.data.Returns[request] = res
1250		h.ReturnedBy = request
1251	
1252		// 记录旧值，落盘失败时整体回滚。
1253		prev := make(map[string]struct {
1254			station string
1255			trail   []Event
1256		}, len(h.Parcels))
1257		for _, id := range h.Parcels {
1258			p := s.data.Parcels[id]
1259			prev[id] = struct {
1260				station string
1261				trail   []Event
1262			}{p.Station, append([]Event(nil), p.Trail...)}
1263			p.Station = h.From
1264			p.Status = statusInStation
1265			p.Trail = append(p.Trail, Event{
1266				Op:         "退回",
1267				Station:    h.From,
1268				From:       h.To,
1269				Request:    request,
1270				RefRequest: handoffReq,
1271				Reason:     reason,
1272				Time:       now,
1273			})
1274		}
1275	
1276		if err := s.save(); err != nil {
1277			delete(s.data.Returns, request)
1278			h.ReturnedBy = ""
1279			for id, old := range prev {
1280				p := s.data.Parcels[id]
1281				p.Station = old.station
1282				p.Trail = old.trail
1283			}
1284			return nil, false, err
1285		}
1286		return res, false, nil
1287	}
1288	
1289	// Dispatch 提交一次配送批次出站。
1290	//
1291	// 首次出站：所有包裹必须已登记、当前归属出发站且状态为在站，否则整批拒绝、不作任何改动；
1292	// 全部满足时整批转为“配送中”（站点仍记出发站），每件追加一条含批次、配送员和时间的
1293	// 出站记录，批次成员按首次提交顺序保存且不可修改。批次号标识一次配送，完成后也不能复用：
1294	// 相同批次号且站点、配送员、包裹集合（与顺序无关）相同，直接返回首次结果，replayed 为 true；
1295	// 批次号相同但内容不同报冲突；失败的首次出站不占用批次号。
1296	func (s *Store) Dispatch(batch, station, courier string, parcels []string, now time.Time) (result *BatchResult, replayed bool, err error) {
1297		if saved, ok := s.data.Batches[batch]; ok {
1298			if saved.RelayedFrom != "" {
1299				return nil, false, fmt.Errorf("批次号 %q 已由续接 %q 创建（来源批次 %q），不能用于出站，内容冲突",
1300					batch, saved.RelayRequest, saved.RelayedFrom)
1301			}
1302			if saved.Station == station && saved.Courier == courier && sameSet(saved.Parcels, parcels) {
1303				return saved, true, nil
1304			}
1305			return nil, false, fmt.Errorf("批次号 %q 已用于一次不同的出站（出发站=%q 配送员=%q），内容冲突", batch, saved.Station, saved.Courier)
1306		}
1307	
1308		// 首次出站：先做全部校验，任何一件不满足都整批拒绝。
1309		for _, id := range parcels {
1310			p, ok := s.data.Parcels[id]
1311			if !ok {
1312				return nil, false, fmt.Errorf("出站失败：包裹 %q 未登记，整批出站未执行", id)
1313			}
1314			if p.Station != station {
1315				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前归属 %q，不在出发站 %q，整批出站未执行", id, p.Station, station)
1316			}
1317			if inc := activeFreeze(p); inc != "" {
1318				return nil, false, fmt.Errorf("出站失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批出站拒绝，整批出站未执行", id, inc)
1319			}
1320			if p.Status != statusInStation {
1321				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前状态为 %q，不是在站，整批出站未执行", id, p.Status)
1322			}
1323		}
1324	
1325		res := &BatchResult{
1326			Batch:    batch,
1327			Station:  station,
1328			Courier:  courier,
1329			Parcels:  append([]string(nil), parcels...),
1330			Time:     now,
1331			Receipts: map[string]*ReceiptEntry{},
1332		}
1333		s.data.Batches[batch] = res
1334	
1335		// 记录旧值，落盘失败时整体回滚。
1336		prev := make(map[string]struct {
1337			status string
1338			trail  []Event
1339		}, len(parcels))
1340		for _, id := range parcels {
1341			p := s.data.Parcels[id]
1342			prev[id] = struct {
1343				status string
1344				trail  []Event
1345			}{p.Status, append([]Event(nil), p.Trail...)}
1346			p.Status = statusDelivering // 站点不变，仍记出发站
1347			p.Trail = append(p.Trail, Event{
1348				Op:      "出站",
1349				Station: station,
1350				Batch:   batch,
1351				Courier: courier,
1352				Time:    now,
1353			})
1354		}
1355	
1356		if err := s.save(); err != nil {
1357			delete(s.data.Batches, batch)
1358			for id, old := range prev {
1359				p := s.data.Parcels[id]
1360				p.Status = old.status
1361				p.Trail = old.trail
1362			}
1363			return nil, false, err
1364		}
1365		return res, false, nil
1366	}
1367	
1368	// Receipt 提交一件包裹在某个配送批次下的回执。
1369	//
1370	// 首次回执：批次必须存在，包裹必须属于该批次、在该批次没有未撤销的回执，且当前仍在该批次
1371	// 配送中；任一不满足则拒绝，不作任何改动。签收后状态为“已签收”；失败表示实物已回到
1372	// 出发站，恢复“在站”，可加入新的配送批次。两种结果都保留站点并追加一条含批次、结果、
1373	// 原因（失败时）、请求号和时间的回执记录；全部成员均有未撤销回执后批次自动完成。
1374	// 已撤销的回执不再占用该件的回执名额，可用新请求号重新回执（见 RevokeReceipt）。
1375	// 相同回执请求号且批次、包裹、结果、清理后的原因相同：直接返回首次结果，replayed 为
1376	// true，不重新检查当前状态，即使失败包裹已进入新批次或该回执已被撤销（重放不恢复回执，
1377	// 结果中可辨认已撤销）；请求号相同但内容不同报冲突。
1378	// 回执请求号与批次号、包裹编号、交接及退回请求号分属独立去重范围，允许同名；
1379	// 失败的首次回执不占用请求号。
1380	func (s *Store) Receipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, err error) {
1381		res, replayed, undo, err := s.applyReceipt(request, batch, parcel, result, reason, now)
1382		if err != nil || replayed {
1383			return res, replayed, err
1384		}
1385		if err := s.save(); err != nil {
1386			undo() // 落盘失败：回滚内存变更，保留原有有效数据
1387			return nil, false, err
1388		}
1389		return res, false, nil
1390	}
1391	
1392	// applyReceipt 在内存台账上校验并应用一条回执（不落盘），是 Receipt 与
1393	// ImportReceipts 共用的核心。全部校验通过后才会改动数据；返回的 undo 可在
1394	// 整体保存失败时撤销本次改动（重放或校验失败时 undo 为 nil）。
1395	func (s *Store) applyReceipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, undo func(), err error) {
1396		if saved, ok := s.data.Receipts[request]; ok {
1397			if saved.Batch == batch && saved.Parcel == parcel && saved.Result == result && saved.Reason == reason {
1398				return saved, true, nil, nil
1399			}
1400			return nil, false, nil, fmt.Errorf("回执请求号 %q 已用于一次不同的回执（批次=%q 包裹=%q 结果=%q），内容冲突",
1401				request, saved.Batch, saved.Parcel, saved.Result)
1402		}
1403	
1404		b, ok := s.data.Batches[batch]
1405		if !ok {
1406			return nil, false, nil, fmt.Errorf("回执失败：批次号 %q 不存在", batch)
1407		}
1408		member := false
1409		for _, id := range b.Parcels {
1410			if id == parcel {
1411				member = true
1412				break
1413			}
1414		}
1415		if !member {
1416			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 不属于批次 %q", parcel, batch)
1417		}
1418		if e, done := b.Receipts[parcel]; done && e.RevokedBy == "" {
1419			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 在批次 %q 中已回执，每件在一个批次只能有一条未撤销回执", parcel, batch)
1420		}
1421		p := s.data.Parcels[parcel] // 批次成员必已登记（载入校验保证）
1422		if p.Status != statusDelivering || currentBatch(p) != batch {
1423			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 当前状态为 %q，不在批次 %q 配送中", parcel, p.Status, batch)
1424		}
1425	
1426		res = &ReceiptResult{
1427			Request: request,
1428			Batch:   batch,
1429			Parcel:  parcel,
1430			Result:  result,
1431			Reason:  reason,
1432			Time:    now,
1433		}
1434		entry := &ReceiptEntry{Request: request, Result: result, Reason: reason, Time: now}
1435	
1436		// 记录旧值，undo 在整体落盘失败时回滚。
1437		oldStatus, oldStation := p.Status, p.Station
1438		oldTrailLen := len(p.Trail)
1439		oldEntry, hadEntry := b.Receipts[parcel] // 被取代的已撤销条目（若有）
1440	
1441		if result == resultSigned {
1442			p.Status = statusSigned // 站点保留不变
1443		} else {
1444			p.Status = statusInStation // 实物已回到出发站，可加入新的配送批次
1445			p.Station = b.Station
1446		}
1447		p.Trail = append(p.Trail, Event{
1448			Op:      "回执",
1449			Station: p.Station,
1450			Batch:   batch,
1451			Result:  result,
1452			Reason:  reason,
1453			Request: request,
1454			Time:    now,
1455		})
1456		b.Receipts[parcel] = entry
1457		s.data.Receipts[request] = res
1458	
1459		undo = func() {
1460			delete(s.data.Receipts, request)
1461			if hadEntry {
1462				b.Receipts[parcel] = oldEntry
1463			} else {
1464				delete(b.Receipts, parcel)
1465			}
1466			p.Status, p.Station = oldStatus, oldStation
1467			p.Trail = p.Trail[:oldTrailLen]
1468		}
1469		return res, false, undo, nil
1470	}
1471	
1472	// ReceiptImportRecord 是回执整批导入文件中的一条记录（已清洗）。
1473	type ReceiptImportRecord struct {
1474		Request string // 回执请求号（与逐件 receipt 共用去重范围）
1475		Batch   string // 配送批次号
1476		Parcel  string // 包裹编号
1477		Result  string // 签收 | 失败
1478		Reason  string // 失败原因（失败时非空，签收时为空）
1479	}
1480	
1481	// ReceiptImportItem 是整批导入中一条记录的处理结果，按文件顺序排列。
1482	type ReceiptImportItem struct {
1483		Record   ReceiptImportRecord // 清洗后的记录内容
1484		Time     time.Time           // 发生时间（重放时为首次保存的时间）
1485		Replayed bool                // true 表示同内容历史重放，未产生新变更
1486		Revoked  bool                // true 表示该回执已被撤销（仅历史重放可能；重放不恢复回执）
1487	}
1488	
1489	// ImportReceipts 按文件顺序整批应用回执记录。
1490	//
1491	// 逐条处理：与逐件 Receipt 共用同一回执请求号去重范围，同请求号且批次、包裹、
1492	// 结果、清理后的原因相同的记录返回首次结果与时间（重放），不检查当前状态、不追加
1493	// 轨迹、不改变批次进度；换内容报冲突。首次回执要求批次存在、包裹属于该批次、
1494	// 尚未在该批次回执且当前仍在该批次配送中（含本文件前面记录已产生的回执）。
1495	// 全部记录可接受时作为一个整体原子落盘；任一记录无效、冲突或受理条件不符，
1496	// 整份拒绝并提示记录位置，台账保持导入前状态，新请求号均不占用。
1497	// 全部为历史重放时不改写台账。
1498	func (s *Store) ImportReceipts(records []ReceiptImportRecord, now time.Time) ([]ReceiptImportItem, error) {
1499		// 在台账副本上按文件顺序试算：任一记录失败直接放弃副本，原台账保持不变。
1500		work, err := s.fork()
1501		if err != nil {
1502			return nil, err
1503		}
1504		items := make([]ReceiptImportItem, 0, len(records))
1505		hasNew := false
1506		for i, rec := range records {
1507			res, replayed, _, err := work.applyReceipt(rec.Request, rec.Batch, rec.Parcel, rec.Result, rec.Reason, now)
1508			if err != nil {
1509				return nil, fmt.Errorf("第 %d 条记录（请求号 %q）：%w", i+1, rec.Request, err)
1510			}
1511			if !replayed {
1512				hasNew = true
1513			}
1514			items = append(items, ReceiptImportItem{Record: rec, Time: res.Time, Replayed: replayed, Revoked: res.RevokedBy != ""})
1515		}
1516		if !hasNew {
1517			return items, nil // 全部为历史重放：不改写台账
1518		}
1519	
1520		// 整体提交：副本替换当前台账后一次原子落盘，失败时恢复导入前状态。
1521		orig := s.data
1522		s.data = work.data
1523		if err := s.save(); err != nil {
1524			s.data = orig
1525			return nil, err
1526		}
1527		return items, nil
1528	}
1529	
1530	// fork 返回当前台账的深拷贝副本，供整批导入试算；副本上的任何改动都不影响原台账。
1531	func (s *Store) fork() (*Store, error) {
1532		buf, err := json.Marshal(s.data)
1533		if err != nil {
1534			return nil, fmt.Errorf("准备回执整批导入失败: %w", err)
1535		}
1536		var cp ledgerFile
1537		if err := json.Unmarshal(buf, &cp); err != nil {
1538			return nil, fmt.Errorf("准备回执整批导入失败: %w", err)
1539		}
1540		return &Store{path: s.path, data: cp}, nil
1541	}
1542	
1543	// RevokeReceipt 撤销一条误录的配送回执：经核实包裹实际仍由原配送员配送，
1544	// 撤销错误的签收或失败登记，不收回实物。包裹与批次取自原回执，不可另选。
1545	//
1546	// 首次撤销：原回执必须存在、未撤销且仍为该件在该批次的有效回执；所属批次
1547	// 未中止、未转交；原回执必须是该包裹最后一条轨迹（其后发生过流转、冻结或
1548	// 解除均拒绝，其他成员的后续操作不阻止撤销），包裹仍在原出发站且状态与回执
1549	// 结果一致。任一不满足则拒绝，不作任何改动。成功后该件恢复原批次配送中，
1550	// 站点、配送员不变，该回执不再计入有效回执（原本已完成的批次恢复配送中，
1551	// 原成员顺序与出站或接手时间保留，其他成员及回执不变）；原回执结果与轨迹
1552	// 永久保留并标记已撤销，追加一条撤销回执记录，回执请求号不删除也不释放。
1553	// 每件同批次最多一条未撤销回执，撤销后可用新回执请求号再次提交签收或失败，
1554	// 也可随原批次中止或续接。撤销不恢复配送前旧交接的退回资格。
1555	// 撤销请求号独立去重，可与其他业务编号同名：相同请求号且原回执、清理后的
1556	// 原因相同，直接返回首次撤销信息和时间，replayed 为 true，不检查现状、不
1557	// 再次改变进度或改写台账（后续重新回执、中止或续接后仍成立）；请求号相同
1558	// 但内容不同报冲突。每条原回执只能撤销一次，换撤销号再次撤销它拒绝；
1559	// 失败的首次撤销不占用请求号。
1560	func (s *Store) RevokeReceipt(request, receiptReq, reason string, now time.Time) (res *RevokeResult, replayed bool, err error) {
1561		if saved, ok := s.data.Revokes[request]; ok {
1562			if saved.Receipt == receiptReq && saved.Reason == reason {
1563				return saved, true, nil
1564			}
1565			return nil, false, fmt.Errorf("撤销请求号 %q 已用于一次不同的撤销（原回执=%q 原因=%q），内容冲突",
1566				request, saved.Receipt, saved.Reason)
1567		}
1568	
1569		rc, ok := s.data.Receipts[receiptReq]
1570		if !ok {
1571			return nil, false, fmt.Errorf("撤销失败：原回执请求号 %q 不存在", receiptReq)
1572		}
1573		if rc.RevokedBy != "" {
1574			return nil, false, fmt.Errorf("撤销失败：原回执 %q 已撤销（撤销请求号 %q），每条原回执只能撤销一次", receiptReq, rc.RevokedBy)
1575		}
1576		b := s.data.Batches[rc.Batch] // 回执所属批次必存在（载入校验保证）
1577		if b.AbortedBy != "" {
1578			return nil, false, fmt.Errorf("撤销失败：批次 %q 已中止（中止请求号 %q），不能撤销其中的回执", rc.Batch, b.AbortedBy)
1579		}
1580		if b.TransferredBy != "" {
1581			return nil, false, fmt.Errorf("撤销失败：批次 %q 已转交（续接请求号 %q），不能撤销其中的回执", rc.Batch, b.TransferredBy)
1582		}
1583		entry := b.Receipts[rc.Parcel]
1584		if entry == nil || entry.Request != receiptReq {
1585			return nil, false, fmt.Errorf("撤销失败：回执 %q 已不是包裹 %q 在批次 %q 的有效回执", receiptReq, rc.Parcel, rc.Batch)
1586		}
1587		p := s.data.Parcels[rc.Parcel] // 批次成员必已登记（载入校验保证）
1588		last := p.Trail[len(p.Trail)-1]
1589		if last.Op != "回执" || last.Request != receiptReq {
1590			return nil, false, fmt.Errorf("撤销失败：包裹 %q 在原回执 %q 之后又发生流转、冻结或解除，不能撤销该回执", rc.Parcel, receiptReq)
1591		}
1592		if p.Station != b.Station {
1593			return nil, false, fmt.Errorf("撤销失败：包裹 %q 当前归属 %q，不在原出发站 %q，不能撤销该回执", rc.Parcel, p.Station, b.Station)
1594		}
1595		want := statusSigned
1596		if rc.Result == resultFailed {
1597			want = statusInStation
1598		}
1599		if p.Status != want {
1600			return nil, false, fmt.Errorf("撤销失败：包裹 %q 当前状态为 %q，与原回执 %q 的结果 %q 不一致，不能撤销",
1601				rc.Parcel, p.Status, receiptReq, rc.Result)
1602		}
1603	
1604		res = &RevokeResult{
1605			Request: request,
1606			Receipt: receiptReq,
1607			Batch:   rc.Batch,
1608			Parcel:  rc.Parcel,
1609			Reason:  reason,
1610			Time:    now,
1611		}
1612		s.data.Revokes[request] = res
1613		rc.RevokedBy = request
1614		entry.RevokedBy = request
1615	
1616		// 记录旧值，落盘失败时整体回滚。
1617		oldStatus := p.Status
1618		oldTrailLen := len(p.Trail)
1619		p.Status = statusDelivering // 恢复原批次配送中，站点与配送员不变
1620		p.Trail = append(p.Trail, Event{
1621			Op:         "撤销回执",
1622			Station:    b.Station,
1623			Batch:      rc.Batch,
1624			Request:    request,
1625			RefRequest: receiptReq,
1626			Reason:     reason,
1627			Time:       now,
1628		})
1629	
1630		if err := s.save(); err != nil {
1631			delete(s.data.Revokes, request)
1632			rc.RevokedBy = ""
1633			entry.RevokedBy = ""
1634			p.Status = oldStatus
1635			p.Trail = p.Trail[:oldTrailLen]
1636			return nil, false, err
1637		}
1638		return res, false, nil
1639	}
1640	
1641	// ReceiptOf 按回执请求号返回回执结果；不存在时返回 nil。
1642	func (s *Store) ReceiptOf(request string) *ReceiptResult {
1643		return s.data.Receipts[request]
1644	}
1645	
1646	// RevokeOf 按撤销请求号返回撤销结果；不存在时返回 nil。
1647	func (s *Store) RevokeOf(request string) *RevokeResult {
1648		return s.data.Revokes[request]
1649	}
1650	
1651	// BatchRevokes 返回一个配送批次相关的全部撤销记录，按撤销时间升序。
1652	func (s *Store) BatchRevokes(batch string) []*RevokeResult {
1653		var out []*RevokeResult
1654		for _, rv := range s.data.Revokes {
1655			if rv.Batch == batch {
1656				out = append(out, rv)
1657			}
1658		}
1659		sort.Slice(out, func(i, j int) bool { return out[i].Time.Before(out[j].Time) })
1660		return out
1661	}
1662	
1663	// Freeze 对一件在站包裹登记异常冻结。
1664	//
1665	// 首次冻结：包裹必须已登记、当前归属指定站点且状态为在站；配送中、已签收或已冻结的
1666	// 包裹不能冻结。成功后站点不变，状态转为异常冻结，追加一条含异常单号、原因、站点和
1667	// 时间的冻结记录。一件包裹同时只能有一张未解除异常单。
1668	// 冻结只是管理记录，不移动实物、不算新流转。
1669	// 异常单号标识一次异常，解除后也不能复用：相同异常单号且包裹、站点、清理后的原因
1670	// 相同，直接返回首次冻结结果与时间，replayed 为 true，不再次冻结（即使该异常单已解除、
1671	// 包裹已发生新的流转，也不检查当前状态）；异常单号相同但内容不同报冲突；
1672	// 失败的首次冻结不占用异常单号。异常单号与包裹编号及其他业务编号分属独立去重范围。
1673	func (s *Store) Freeze(incident, parcel, station, reason string, now time.Time) (res *FreezeResult, replayed bool, err error) {
1674		if saved, ok := s.data.Freezes[incident]; ok {
1675			if saved.Parcel == parcel && saved.Station == station && saved.Reason == reason {
1676				return saved, true, nil
1677			}
1678			return nil, false, fmt.Errorf("异常单号 %q 已用于一次不同的冻结（包裹=%q 站点=%q 原因=%q），内容冲突",
1679				incident, saved.Parcel, saved.Station, saved.Reason)
1680		}
1681	
1682		p, ok := s.data.Parcels[parcel]
1683		if !ok {
1684			return nil, false, fmt.Errorf("冻结失败：包裹 %q 未登记，冻结未执行", parcel)
1685		}
1686		if p.Station != station {
1687			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前归属 %q，不在指定站点 %q，冻结未执行", parcel, p.Station, station)
1688		}
1689		if p.Status != statusInStation {
1690			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前状态为 %q，仅在站包裹可以冻结，冻结未执行", parcel, p.Status)
1691		}
1692	
1693		res = &FreezeResult{
1694			Incident: incident,
1695			Parcel:   parcel,
1696			Station:  station,
1697			Reason:   reason,
1698			Time:     now,
1699		}
1700		s.data.Freezes[incident] = res
1701	
1702		// 记录旧值，落盘失败时整体回滚。
1703		oldStatus := p.Status
1704		oldTrail := append([]Event(nil), p.Trail...)
1705		p.Status = statusFrozen // 站点不变
