1894	// BatchAbort 返回一个配送批次的中止结果；批次不存在或未中止时返回 nil。
1895	func (s *Store) BatchAbort(batch string) *AbortResult {
1896		b, ok := s.data.Batches[batch]
1897		if !ok || b.AbortedBy == "" {
1898			return nil
1899		}
1900		return s.data.Aborts[b.AbortedBy]
1901	}
