1903	// Transfer 把原批次全部尚未回执的包裹在配送途中整批交给另一配送员：
1904	// 新建批次继续配送，无需回站。成员与站点取自原批次，不允许另选成员或站点。
1905	//
1906	// 首次续接：原批次必须存在、仍开放（未中止、未转交）且有未回执成员；新批次号
1907	// 必须从未被出站或续接使用；新配送员必须与原配送员不同。未回执成员必须全部仍在
1908	// 原批次配送中且归属出发站，任一不符整批拒绝、不作任何改动。已回执成员不检查也
1909	// 不变更，其后续流转或冻结不阻止续接。全部满足时新批次按原成员顺序接纳全部未
1910	// 回执件，沿用出发站，记录新配送员及接手时间；包裹保持“配送中”及原站点，当前
1911	// 配送归属切换到新批次，各追加一条含请求号、前后批次、新配送员、站点、原因和
1912	// 时间的续接记录。原批次永久关闭为“已转交”，原成员、配送员、出站时间与真实
1913	// 回执保留不变；转交不算回执、收回或再次出站。续接算新的流转，续接后不能退回
1914	// 配送前的旧交接。
1915	// 续接请求号独立去重，可与批次号、包裹号及其他业务编号同名：相同请求号且原批次、
1916	// 新批次、新配送员、清理后的原因相同，直接返回首次转交集合、续接信息及时间，
1917	// replayed 为 true，不检查现状、不重算成员、不改写台账；请求号相同但内容不同报
1918	// 冲突；失败的首次续接不占用请求号。
1919	func (s *Store) Transfer(request, fromBatch, toBatch, courier, reason string, now time.Time) (res *TransferResult, replayed bool, err error) {
1920		if saved, ok := s.data.Transfers[request]; ok {
1921			if saved.FromBatch == fromBatch && saved.ToBatch == toBatch && saved.ToCourier == courier && saved.Reason == reason {
1922				return saved, true, nil
1923			}
1924			return nil, false, fmt.Errorf("续接请求号 %q 已用于一次不同的续接（原批次=%q 新批次=%q 新配送员=%q），内容冲突",
1925				request, saved.FromBatch, saved.ToBatch, saved.ToCourier)
1926		}
1927	
1928		b, ok := s.data.Batches[fromBatch]
1929		if !ok {
1930			return nil, false, fmt.Errorf("续接失败：原批次号 %q 不存在", fromBatch)
1931		}
1932		if b.AbortedBy != "" {
1933			return nil, false, fmt.Errorf("续接失败：批次 %q 已中止（中止请求号 %q），不能续接", fromBatch, b.AbortedBy)
1934		}
1935		if b.TransferredBy != "" {
1936			return nil, false, fmt.Errorf("续接失败：批次 %q 已转交（续接请求号 %q），不能再次续接", fromBatch, b.TransferredBy)
1937		}
1938		if _, used := s.data.Batches[toBatch]; used {
1939			return nil, false, fmt.Errorf("续接失败：新批次号 %q 已被出站或续接使用，不能复用", toBatch)
1940		}
1941		if courier == b.Courier {
1942			return nil, false, fmt.Errorf("续接失败：新配送员 %q 不能与原批次 %q 的配送员相同", courier, fromBatch)
1943		}
1944	
1945		// 按原成员顺序挑出全部未回执成员（批次仍开放，必至少有一件）。
1946		moved := make([]string, 0, len(b.Parcels)-len(b.Receipts))
1947		for _, pid := range b.Parcels {
1948			if e, done := b.Receipts[pid]; !done || e.RevokedBy != "" {
1949				moved = append(moved, pid)
1950			}
1951		}
1952		if len(moved) == 0 {
1953			return nil, false, fmt.Errorf("续接失败：批次 %q 没有未回执成员，不能续接", fromBatch)
1954		}
1955	
1956		// 先做全部校验：未回执成员必须仍在原批次配送中且归属出发站，任一不符整批拒绝。
1957		for _, pid := range moved {
1958			p := s.data.Parcels[pid] // 批次成员必已登记（载入校验保证）
1959			if p.Status != statusDelivering || currentBatch(p) != fromBatch || p.Station != b.Station {
1960				return nil, false, fmt.Errorf("续接失败：包裹 %q 当前归属 %q、状态 %q，不在批次 %q 从出发站 %q 配送中，整批续接未执行",
1961					pid, p.Station, p.Status, fromBatch, b.Station)
1962			}
1963		}
1964	
1965		res = &TransferResult{
1966			Request:     request,
1967			FromBatch:   fromBatch,
1968			ToBatch:     toBatch,
1969			Station:     b.Station,
1970			FromCourier: b.Courier,
1971			ToCourier:   courier,
1972			Reason:      reason,
1973			Parcels:     append([]string(nil), moved...),
1974			Time:        now,
1975		}
1976		s.data.Transfers[request] = res
1977		s.data.Batches[toBatch] = &BatchResult{
1978			Batch:        toBatch,
1979			Station:      b.Station,
1980			Courier:      courier,
1981			Parcels:      append([]string(nil), moved...),
1982			Time:         now,
1983			Receipts:     map[string]*ReceiptEntry{},
1984			RelayedFrom:  fromBatch,
1985			RelayRequest: request,
1986		}
1987		b.TransferredBy = request
1988	
1989		// 记录旧值，落盘失败时整体回滚。包裹保持“配送中”及原站点，只追加续接轨迹。
1990		prev := make(map[string][]Event, len(moved))
1991		for _, pid := range moved {
1992			p := s.data.Parcels[pid]
1993			prev[pid] = append([]Event(nil), p.Trail...)
1994			p.Trail = append(p.Trail, Event{
1995				Op:        "续接",
1996				Station:   b.Station,
1997				Batch:     toBatch,
1998				FromBatch: fromBatch,
1999				Courier:   courier,
2000				Request:   request,
2001				Reason:    reason,
2002				Time:      now,
2003			})
2004		}
2005	
2006		if err := s.save(); err != nil {
2007			delete(s.data.Transfers, request)
2008			delete(s.data.Batches, toBatch)
2009			b.TransferredBy = ""
2010			for pid, old := range prev {
2011				s.data.Parcels[pid].Trail = old
2012			}
2013			return nil, false, err
2014		}
2015		return res, false, nil
2016	}
