2032	// Ship 提交一次站间发运：整单包裹离开源站、尚未到达目的站。
2033	//
2034	// 首次发运：每件包裹必须已登记、当前归属源站且状态为在站；任一不满足则整单拒绝，
2035	// 不作任何改动（在途、配送中、已签收或已冻结的包裹均不满足）。全部满足时整单转为
2036	// “站间在途”（归属站点暂记源站），每件追加一条含运输单号、两站和时间的发运记录；
2037	// 成员按首次提交顺序保存，保存后不可修改。每件包裹同时最多属于一张未接收运输单。
2038	// 发运算新的流转：发运后不能退回此前的旧交接；运输单不是交接，不能作为退回的原交接。
2039	// 运输单号独立于已有各类编号，接收后也不释放：相同运输单号且源站、目的站、包裹集合
2040	// 相同（集合顺序无关），直接返回首次成员顺序与发运时间，replayed 为 true，不检查现状、
2041	// 不追加轨迹、不改写台账；运输单号相同但内容不同报冲突；失败的首次发运不占用运输单号。
2042	func (s *Store) Ship(shipment, from, to string, parcels []string, now time.Time) (res *ShipmentResult, replayed bool, err error) {
2043		if saved, ok := s.data.Shipments[shipment]; ok {
2044			if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
2045				return saved, true, nil
2046			}
2047			return nil, false, fmt.Errorf("运输单号 %q 已用于一次不同的发运（源站=%q 目的站=%q），内容冲突", shipment, saved.From, saved.To)
2048		}
2049	
2050		// 首次发运：先做全部校验，任何一件不满足都整单拒绝。
2051		for _, id := range parcels {
2052			p, ok := s.data.Parcels[id]
2053			if !ok {
2054				return nil, false, fmt.Errorf("发运失败：包裹 %q 未登记，整单发运未执行", id)
2055			}
2056			if p.Station != from {
2057				return nil, false, fmt.Errorf("发运失败：包裹 %q 当前归属 %q，不在源站 %q，整单发运未执行", id, p.Station, from)
2058			}
2059			if p.Status != statusInStation {
2060				return nil, false, fmt.Errorf("发运失败：包裹 %q 当前状态为 %q，不是在站，整单发运未执行", id, p.Status)
2061			}
2062		}
2063	
2064		res = &ShipmentResult{
2065			Shipment: shipment,
2066			From:     from,
2067			To:       to,
2068			Parcels:  append([]string(nil), parcels...),
2069			Time:     now,
2070		}
2071		s.data.Shipments[shipment] = res
2072	
2073		// 记录旧值，落盘失败时整体回滚。
2074		prev := make(map[string]struct {
2075			status string
2076			trail  []Event
2077		}, len(parcels))
2078		for _, id := range parcels {
2079			p := s.data.Parcels[id]
2080			prev[id] = struct {
2081				status string
2082				trail  []Event
2083			}{p.Status, append([]Event(nil), p.Trail...)}
2084			p.Status = statusInTransit // 归属站点暂记源站，整单转为站间在途
2085			p.Trail = append(p.Trail, Event{
2086				Op:       "发运",
2087				Station:  from,
2088				From:     from,
2089				To:       to,
2090				Shipment: shipment,
2091				Time:     now,
2092			})
2093		}
2094	
2095		if err := s.save(); err != nil {
2096			delete(s.data.Shipments, shipment)
2097			for id, old := range prev {
2098				p := s.data.Parcels[id]
2099				p.Status = old.status
2100				p.Trail = old.trail
2101			}
2102			return nil, false, err
2103		}
2104		return res, false, nil
2105	}
