2107	// Receive 提交一次整单到站接收：运输单全部成员到达目的站。成员取自运输单，不另选。
2108	//
2109	// 首次接收：运输单必须存在且尚未接收，接收站点必须等于运输单目的站，全部成员必须
2110	// 仍归该单在途且归属源站；任一不满足则整单拒绝，不作任何改动。成功时按发运保存
2111	// 顺序将全部成员改归目的站、恢复“在站”，各追加一条含运输单号、两站、接收请求号
2112	// 和时间的接收记录，运输单永久标记为已接收，随后可继续在站作业。
2113	// 接收算新的流转：接收后不能退回此前的旧交接。
2114	// 接收请求号与运输单号及已有各类编号分属独立去重范围，允许同名：相同接收请求号且
2115	// 运输单、接收站点相同，直接返回首次接收结果与时间，replayed 为 true，不检查现状、
2116	// 不追加轨迹、不改写台账（接收后包裹再流转也照常重放）；请求号相同但内容不同报冲突；
2117	// 换请求号再次接收同一运输单拒绝；失败的首次接收不占用请求号。
2118	func (s *Store) Receive(request, shipment, station string, now time.Time) (res *ReceiveResult, replayed bool, err error) {
2119		if saved, ok := s.data.Receives[request]; ok {
2120			if saved.Shipment == shipment && saved.Station == station {
2121				return saved, true, nil
2122			}
2123			return nil, false, fmt.Errorf("接收请求号 %q 已用于一次不同的接收（运输单=%q 接收站点=%q），内容冲突",
2124				request, saved.Shipment, saved.Station)
2125		}
2126	
2127		sh, ok := s.data.Shipments[shipment]
2128		if !ok {
2129			return nil, false, fmt.Errorf("接收失败：运输单号 %q 不存在", shipment)
2130		}
2131		if sh.ReceivedBy != "" {
2132			return nil, false, fmt.Errorf("接收失败：运输单 %q 已接收（接收请求号 %q），每单只能成功接收一次", shipment, sh.ReceivedBy)
2133		}
2134		if station != sh.To {
2135			return nil, false, fmt.Errorf("接收失败：接收站点 %q 不是运输单 %q 的目的站 %q，整单接收未执行", station, shipment, sh.To)
2136		}
2137	
2138		// 先做全部校验：全部成员必须仍归该单在途且归属源站，任一不符整单拒绝。
2139		for _, pid := range sh.Parcels {
2140			p := s.data.Parcels[pid] // 运输单成员必已登记（载入校验保证）
2141			if p.Status != statusInTransit || p.Station != sh.From {
2142				return nil, false, fmt.Errorf("接收失败：包裹 %q 当前归属 %q、状态 %q，不在运输单 %q 从源站 %q 在途，整单接收未执行",
2143					pid, p.Station, p.Status, shipment, sh.From)
2144			}
2145		}
2146	
2147		res = &ReceiveResult{
2148			Request:  request,
2149			Shipment: shipment,
2150			Station:  station,
2151			Parcels:  append([]string(nil), sh.Parcels...),
2152			Time:     now,
2153		}
2154		s.data.Receives[request] = res
