	if _, _, code := runCLI(t, dbPath, "handoff", "--request", "R2", "--from", "站点B", "--to", "站点C",
		"--parcel", "P001"); code != 0 {
		t.Fatalf("接收后应能继续在站作业: code=%d", code)
	}
}
