			status  string
			trail   []Event
		}{p.Station, p.Status, append([]Event(nil), p.Trail...)}
		p.Station = sh.To
		p.Status = statusInStation
		p.Trail = append(p.Trail, Event{
			Op:       "接收",
			Station:  sh.To,
			From:     sh.From,
			To:       sh.To,
			Shipment: shipment,
			Request:  request,
			Time:     now,
		})
	}

