	if err != nil {
		fmt.Fprintf(stderr, "%s receive: %v\n", appName, err)
		return exitBusiness
	}
	cleanShipment, err := cleanID("运输单号", *shipment)
	if err != nil {
		fmt.Fprintf(stderr, "%s receive: %v\n", appName, err)
		return exitBusiness
