73			t.Fatalf("全部接收的运输单查询输出不符: code=%d out=%s", code, out)
74		}
75	
76		// 重放：显式集合换序与不选成员均返回首次结果；同号切换方式冲突；全部接收后新请求拒绝。
77		out, _, code = runCLI(t, dbPath, "receive", "--request", "RS1", "--shipment", "S1", "--station", "站点B",
78			"--parcel", "P001")
79		if code != 0 || !strings.Contains(out, "重复提交") {
80			t.Fatalf("显式集合重放应返回首次结果: code=%d out=%s", code, out)
81		}
82		out, _, code = runCLI(t, dbPath, "receive", "--request", "RS2", "--shipment", "S1", "--station", "站点B")
83		if code != 0 || !strings.Contains(out, "重复提交") || !strings.Contains(out, "本次接收包裹（2 件）") {
84			t.Fatalf("不选成员重放应返回首次集合: code=%d out=%s", code, out)
85		}
86		_, errText, code := runCLI(t, dbPath, "receive", "--request", "RS1", "--shipment", "S1", "--station", "站点B")
87		if code != exitBusiness || !strings.Contains(errText, "冲突") {
88			t.Fatalf("同号切换方式应报冲突(1): code=%d err=%s", code, errText)
89		}
90		if _, _, code := runCLI(t, dbPath, "receive", "--request", "RS9", "--shipment", "S1", "--station", "站点B"); code != exitBusiness {
91			t.Fatalf("全部接收后新请求应拒绝(1): code=%d", code)
92		}
93	
94		// 显式集合参数校验：空集合元素、集合内重复、选中件不属于原单，均退出码 1。
95		if _, _, code := runCLI(t, dbPath, "receive", "--request", "RQ1", "--shipment", "S1", "--station", "站点B",
96			"--parcel", "  "); code != exitBusiness {
97			t.Fatalf("空白包裹编号应失败(1): code=%d", code)
98		}
99		if _, _, code := runCLI(t, dbPath, "receive", "--request", "RQ1", "--shipment", "S1", "--station", "站点B",
100			"--parcel", "P001", "--parcel", "P001"); code != exitBusiness {
101			t.Fatalf("集合内重复应失败(1): code=%d", code)
102		}
103	}
